@php
$health=function($r){
    $today=now()->startOfDay();
    if($r->to_date && \Carbon\Carbon::parse($r->to_date)->lt($today)) return ['Expired','red'];
    if($r->to_date && \Carbon\Carbon::parse($r->to_date)->between($today,now()->addDays(7))) return ['Expiring','amber'];
    if(!$r->from_date || !$r->to_date) return ['Date issue','red'];
    if($r->is_oneway!=='Yes' && $r->is_roundtrip!=='Yes' && ($r->is_multicity??'No')!=='Yes') return ['No journey','red'];
    if(!collect(['is_economy','is_peconomy','is_business','is_fclass'])->contains(fn($f)=>$r->{$f}==='Yes')) return ['No cabin','red'];
    return ['Healthy','green'];
};
@endphp
